 if(type===0)icon='<path fill="#263b43" d="M17 28h30v18H17zM13 31h5v8h-5zM46 31h5v8h-5z"/><path fill="#647c7b" d="M20 30h24v13H20z"/><path fill="#d3d5bc" d="M18 25h28v5H18zM27 21h10v5H27z"/><path fill="#c0cdbb" d="M21 32h4v8h-4z"/><path fill="#faf0d2" d="M26 15h2v4h-2zM36 13h2v5h-2z"/>';
