 return kitchenSVG('<path fill="#273640" d="M5 4h54v56H5z"/><path fill="'+colors[type]+'" d="M8 7h48v50H8z"/><path fill="#fff0c0" d="M10 9h44v3H10zM10 12h3v40h-3z"/><path fill="#9d7f54" d="M11 53h42v2H11z"/>'+icon);
