function sortedFoods(rows,filter,sort){return rows.filter(x=>foodMatches(x.w,filter)).sort((a,b)=>{const x=dishSupplyEffect(a.w),y=dishSupplyEffect(b.w);return (sort==='quality'?b.w.t-a.w.t:sort==='freshness'?(a.w.fresh||0)-(b.w.fresh||0):(y[sort]||0)-(x[sort]||0))||a.index-b.index;});}
