/* 合成與預覽共用的材料、路徑判定 */
function moldMaterials(i,board=g){
  const ore=j=>board[j]&&board[j].k==='o'?board[j].t:-1;
  for(let t=4;t>=0;t--){
    const seen=new Set(),cells=[];
    nb(i).forEach(j=>{
      if(ore(j)===t&&!seen.has(j)){seen.add(j);cells.push(j)}
    });
    for(let k=0;k<cells.length;k++)nb(cells[k]).forEach(j=>{
      if(j!==i&&ore(j)===t&&!seen.has(j)){seen.add(j);cells.push(j)}
    });
    if(cells.length>=2)return {t,cells};
  }
  return null;
}
function forgePath(i,board=g){
  if(board[i]?.k!=='p')return null;
  const gr=group(i,board);
  if(gr.length<3)return null;
  if(gr.length===4)return workshopFour(gr,i);
  for(let n=gr.length;n>=3;n--){
    const path=workshopChain(gr.slice(0,n));if(path)return path;
  }
  return null;
}

function place(i,s2){
  if(day===0&&tutStage===2&&i!==17){say('請把鑽石模具放在棋盤中央的提示格。');return false;}
  if(cellBlock(i)){say(cellBlock(i));return false;}
  const mat=moldMaterials(i);
  if(!mat){say("模具要放在兩顆相鄰同階礦石的旁邊");return}
  const t=mat.t;
  const mm=mat.cells.reduce((a,j)=>a+(g[j].m||0),0)+(magicSet.has(i)?5:0);
  const oreFrom=expandedGameEnabled()?mat.cells.map(j=>({i:j,h:oreH(g[j].t,'',g[j].m||0),key:workshopItemKey(g[j])})):null;mat.cells.forEach(j=>g[j]=null);
  const s=s2!==undefined?s2:MQ.shift();
  if(s2===undefined&&MQ.length<3)MQ.push(rollM());
  g[i]=s===3?{k:'d',t,m:mm}:{k:'p',t,s,m:mm};
  tool=-1;fresh=i;
  say((mat.cells.length>2?"一次消耗了 "+mat.cells.length+" 顆礦石！":"")
    +(magicSet.has(i)?" ✨ 附魔 +1 層（額外售價 +5 金幣）":""));
  if(expandedGameEnabled()){const ev={step:0,tg:i,from:oreFrom,to:[i],res:{[i]:workshopPieceHTML(g[i])},keys:{[i]:workshopItemKey(g[i])}};fx.push(ev);const begin=fx.length;if(s!==3)forge(i);fx.slice(begin).forEach(e=>e.step++);}else if(s!==3)forge(i);
  return true;
}
function mergeGroup(i,lvl=0){
 const plan=workshopMaterialPlan(i,g);if(!plan)return [];const source=new Map(plan.cells.map(j=>[j,{...g[j]}]));plan.cells.forEach(j=>g[j]=null);
 for(const batch of plan.groups){const magic=batch.cells.reduce((n,j)=>n+(source.get(j).m||0),0),w={k:'o',t:batch.tier,m:magic};g[batch.target]=w;
  fx.push({step:lvl,tg:batch.target,from:batch.cells.map(j=>({i:j,h:oreH(source.get(j).t,'',source.get(j).m||0),key:workshopItemKey(source.get(j))})),to:[batch.target],res:{[batch.target]:oreH(w.t,'',w.m)},keys:{[batch.target]:workshopItemKey(w)}});
 }return plan.groups.map(b=>b.target);
}
function auto(i,l0=0){
  if(!sk('mm'))return;
  let up=0,q=[[i,l0]];
  while(q.length){
    const [p,l]=q.shift();
    if(!g[p]||g[p].k!=='o'||g[p].t>=4)continue;
    const r=mergeGroup(p,l);
    if(r.length){up++;q.push(...r.map(x=>[x,l+1]))}
  }
  if(up){
    say(up>1?"連鎖升階 ×"+up+"！":"自動合成升階！");
    if(up>=2&&typeof triggerChainComboFX==='function'){triggerChainComboFX('grid',up,'⚡ CHAIN ×'+up+' 連鎖升階');addWorkshopFever('forge',12*up);}
    qEach('chain',q=>{if(up>=q.n)qProg(q,q.n)});
  }
}
function merge(i){
  const c=g[i];
  if(c.k==='o'&&c.t>=4){say("已是最高階礦石");return}
  const gr=group(i);
  if(gr.length<3){say("需要三個以上相連的同類");return}
  if(c.k==='o'){
    if(!sk('mm'))say("需要「合成大師」技能才能合成礦石");
    else auto(i);
    return;
  }
  if(!forge(i))say("胚需要排成直線或彎線才能合成");
}
function forge(i){
  const path=forgePath(i);
  if(!path)return false;
  const n=path.length,tris=[];
  for(let k=0;k<n-2;k++)tris.push(path.slice(k,k+3));
  const source=new Map(path.map(j=>[j,{...g[j]}]));
  const spots=workshopRecipeWindows(path,i).map(b=>b.target);
  const info=tris.map(t=>({
    w:COMBO.indexOf(t.map(j=>g[j].s).sort().join("")),
    wt:Math.floor(t.reduce((s,j)=>s+g[j].t,0)/3),
    cells:t,
    cs:t.map(j=>g[j].t).sort((x,y)=>y-x),
    parts:t.map(j=>({s:g[j].s,t:g[j].t})),
    mm:t.reduce((a,j)=>a+(g[j].m||0),0)
  }));
  const cb=typeof contractBonuses==='function'?contractBonuses():{};
  const hadHotNeighbor=info.map(f=>f.cells.some(j=>nb(j).some(n=>!path.includes(n)&&heat[n]>0)));
  const pt=path.map(j=>g[j].t);
  path.forEach(j=>{g[j]=null;heat[j]=hotSteps();justHeated.add(j)});
  const msgs=[];
  info.forEach((f,k)=>{
    let b=0,dm=0;const dts=[];
    [...new Set(f.cells.flatMap(nb))]
      .filter(j=>g[j]&&g[j].k==='d')
      .slice(0,3).forEach(j=>{
        b+=.3*(g[j].t+1);dm+=g[j].m||0;
        dts.push(g[j].t);g[j]=null;heat[j]=0;justHeated.delete(j);
      });
    const emberM=(cb.emberTemper&&hadHotNeighbor[k])?10:0;
    g[spots[k]]={k:'w',t:f.wt,c:f.w,b,cs:f.cs,parts:f.parts,m:f.mm+dm+emberM,dts,statVersion:1,...(info.length>=2?{chainBonus:true}:{})};
    const wo=applyWeaponElement(g[spots[k]],spots[k]);recordWeaponCraft(wo);
    if(cb.forgeCraftGold){coins+=cb.forgeCraftGold;earned+=cb.forgeCraftGold;dEarn+=cb.forgeCraftGold;}
    const ev={step:0,tg:spots[k],from:f.cells.map(j=>({i:j,h:workshopPieceHTML(source.get(j)),key:workshopItemKey(source.get(j))})),to:[spots[k]],res:{[spots[k]]:workshopItemHTML(wo)},keys:{[spots[k]]:workshopItemKey(wo)},forged:[]};fx.push(ev);
    const emberGold=consumeAutumnForgeReward();if(emberGold)toast("🍂 落葉餘燼：鍛造獎金 +100 金幣（不計分）");
    (ev.forged||(ev.forged=[])).push({w:wo,i:spots[k]});
    if(day>0&&!testRun)rememberWeapon(wo);
    if(rankOf(wo)>rankOf(best[f.w]))
      best[f.w]={t:wo.t,cs:wo.cs,parts:wo.parts,b:wo.b,dts:wo.dts,m:wo.m,element:wo.element,stars:wo.stars,starXp:wo.starXp,statVersion:1};
    qOnForgeStats(wo);

    msgs.push(NM[f.wt]+"級"+WN[f.w]+"（"+materialNote(wo)+"）"+(b?"（💎+"+Math.round(b*100)+"%）":"")+(emberM?"（🔥淬火+2層）":""));
  });
  if(typeof addWorkshopFever==='function'){
    addWorkshopFever('forge',16*info.length+(info.length>=2&&cb.twinCraft?20:0));
    if(info.length>=2)triggerChainComboFX('grid',info.length,'🔥 CHAIN ×'+info.length+' 連續鍛造！');
  }
  say("鍛造出 "+msgs.join("、")+"！");
  qEach('forge2',q=>{if(info.length>=q.n)qProg(q,q.n)});
  burnLeaves();
  const free=path.filter(j=>!spots.includes(j));
  if(free.length){
    const r=free[rnd(free.length)];
    const pr=sk('mm')>=3?.5:sk('mm')===2?.25:0;
    const dt=Math.random()<pr?pt[rnd(pt.length)]:0;
    g[r]={k:'o',t:dt};
    auto(r,1);
  }
  saveHi();
  return true;
}

function removeOrder(k){
  const card=document.querySelector('.od[data-k="'+k+'"]');
  const r=card&&card.getBoundingClientRect(),gh=card&&card.cloneNode(true);
  dServed++;
  if(dLeft>0){
    orders[k]=dq.shift();dLeft--;
    enter.set(k,Date.now()+600);gameTimeout(bell,600);
  }else{
    orders.splice(k,1);exitMs=900;
  }
  if(gh)leave(gh,r);
}
function checkWait(){
  let n=0;
  for(let k=orders.length-1;k>=0;k--){
    if(orders[k].wait<=0){removeOrder(k);n++}
  }
  if(n){qEach('safe',q=>q.failed=true);lives-=n;say("客人等太久離開了！生命 -"+n)}
}
function gameOver(why){active=false;cancelKitchenDrag();clearKitchenIngredientFlights();clearKitchenDepartures();$("kitchenP").hidden=true;$("kitchenModal").hidden=true;
  stopExpeditionPlayback();$("expeditionP").style.display="none";$("weaponStatsP").style.display="none";
  $("townP").style.display="none";
  saveHi();removeSave(runId);
  if(day===0){
    ov("格子滿了","教學卡住了，重新試一次吧！","重做教學",()=>start("tut"));
    return;
  }
  ov("遊戲結束",why+"第 "+day+" 天，累計分數 "+score()+"。服務 "+all+" 位客人、完成 "+qDone+" 個任務。歷史最高 "+hi+"。"+rec(),"再來一局",beginNewCharacter);
}
function cancelOrder(k){
  if(!orders[k])return;
  qEach('safe',q=>q.failed=true);lives--;say("已取消訂單，生命 -1");removeOrder(k);render();
  const T=exitMs;exitMs=0;
  gameTimeout(()=>{
    if(lives<=0)gameOver("生命用完了。");
    else if(!orders.length)endDay();
  },T);
}
function dropGem(t){
  const em=[];
  g.forEach((x,j)=>{if(!x&&heat[j]<=0&&!cellBlock(j))em.push(j)});
  if(!em.length)return;
  const j=em[rnd(em.length)];
  g[j]={k:'d',t,m:0};fresh=j;
  say(forgeMessageText()+" 💎 掉落一顆"+NM[t]+"鑽！");
}
function sellW(c,k,clear){
  if(c?.protected){toast('這把武器已受保護，請先取消保護');return false;}const o=orders[k];
  if(o.c!==null&&o.c!==c.c){say("這位客人要的是"+WN[o.c]);return false}
  if(c.t<o.t){say("品質不夠，這位客人需要"+NM[o.t]+"級以上");return false}
  const mg=c.m||0,p=salePrice(c,o);
  coins+=p;earned+=p;dEarn+=p;dMagic+=mg*10;
  clear();all++;dSold++;saveHi();
  const magicGold=mg?p-salePrice({...c,m:0},o):0;
  say("成交！+"+p+" 金幣"+(mg?"（附魔 "+weaponStats(c).stacks+" 層 · 額外金幣 +"+magicGold+"）":"")
    +(sk("mc")?"，大商人 +"+10*sk("mc")+"%":"")+seasonSaleNote(c)+(guestPreferenceBonus(c,o,false)?'，喜好 +10%':''));
  qOnSale(c,p);recordFestival('weapon',c);
  if(typeof addWorkshopFever==='function')addWorkshopFever('forge',18+(contractBonuses().saleFever||0));
  if(c.dts&&c.dts.length&&sk('gc')>=2&&Math.random()<.25)
    dropGem(sk('gc')>=3?Math.max(...c.dts):0);
  removeOrder(k);
  return true;
}
const sellTo=(i,k)=>sellW(g[i],k,()=>{g[i]=null});
function over(){
  if(legendProjects.length)return false;
  if(!g.every((c,i)=>c||heat[i]>0||isOff(i)||cellBlock(i)))return false;
  // 有可用的暴風雪（或買得起）時，保留解除過熱死局的機會。
  if(heat.some((h,i)=>h>0&&!g[i]&&!cellBlock(i))&&
    ((hand&&hand.k==='z')||bag.some(it=>it.k==='z')||(coins>=BLIZZP&&shopRemaining('tool')>0)))return false;
  if(pack.some(w=>w&&sellable(w)))return false;
  return !g.some((c,i)=>c&&(
    c.k==='w'?(sellable(c)||pack.includes(null))
    :c.k==='d'?false
    :c.k==='o'&&!sk('mm')?false
    :!(c.k==='o'&&c.t>=4)&&group(i).length>=3
  ));
}

