 const flag=(x,y,i)=>`<g transform="translate(${x} ${y})"><path fill="#6d624c" d="M-1-1h2v21h-2z"/><path fill="#e3c16e" d="M-2-3h4v4h-4z"/><g class="castle-flag-cloth" style="--flag-delay:-${i*.53}s"><path fill="#663b42" d="M1 1h18v3h4l-4 5 4 5h-9v-2H1z"/><path fill="#b66362" d="M2 2h15v3h4l-4 4 3 3h-7v-2H2z"/><path fill="#e2bb70" d="M5 3h2v6H5zM4 5h5v2H4z"/><path fill="#e7aa82" opacity=".7" d="M10 3h6v2h-6z"/></g></g>`;
