 if(c===2){const max=Math.round(s.def*v.cap),gain=Math.min(Math.round(s.def*v.gain),Math.max(0,max-(b.bladeWardGained||0)));b.shield+=gain;b.bladeWardGained=(b.bladeWardGained||0)+gain;if(gain)row.text+=' · 護刃 +'+gain+'盾';}
