 ['atk','def','spd'].forEach(k=>{const avg=values.reduce((a,s)=>a+s[k],0)/values.length;core[k]=Math.round(Math.max(ref[k]*1.4,(ref[k]*.65+avg*.35)*l.scale)*(LEGEND_BONUS[id][k]||1));});
